create type public.org_role as enum ('owner','admin','operator','viewer','developer');
create type public.environment as enum ('production','sandbox');
create type public.company_status as enum ('configuring');
create type public.change_origin as enum ('panel','api');
create type public.invitation_status as enum ('pending','accepted','revoked');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', avatar_url text, theme text not null default 'dark' check(theme in ('dark','light')), environment public.environment not null default 'production', last_organization_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select,insert,update on public.profiles to authenticated; grant all on public.profiles to service_role; alter table public.profiles enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid()); create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create table public.platform_admins(user_id uuid primary key references public.profiles(id) on delete cascade, created_by uuid, created_at timestamptz not null default now());
grant select on public.platform_admins to authenticated; grant all on public.platform_admins to service_role; alter table public.platform_admins enable row level security;
create policy admins_self on public.platform_admins for select to authenticated using(user_id=auth.uid());
create function public.is_platform_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.platform_admins where user_id=auth.uid()) $$;
revoke all on function public.is_platform_admin() from public; grant execute on function public.is_platform_admin() to authenticated,service_role;
create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name))>0), slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), created_by uuid not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select,insert,update on public.organizations to authenticated; grant all on public.organizations to service_role; alter table public.organizations enable row level security;
create table public.organization_members(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.org_role not null, created_at timestamptz not null default now(), unique(organization_id,user_id));
grant select on public.organization_members to authenticated; grant all on public.organization_members to service_role; alter table public.organization_members enable row level security;
create function public.is_org_member(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members where organization_id=org_id and user_id=auth.uid()) $$;
create function public.has_org_role(org_id uuid, roles public.org_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members where organization_id=org_id and user_id=auth.uid() and role=any(roles)) $$;
revoke all on function public.is_org_member(uuid),public.has_org_role(uuid,public.org_role[]) from public; grant execute on function public.is_org_member(uuid),public.has_org_role(uuid,public.org_role[]) to authenticated,service_role;
create policy organizations_read on public.organizations for select to authenticated using(public.is_org_member(id) or public.is_platform_admin());
create policy organizations_create on public.organizations for insert to authenticated with check(public.is_platform_admin() and created_by=auth.uid());
create policy organizations_update on public.organizations for update to authenticated using(public.has_org_role(id,array['owner','admin']::public.org_role[]) or public.is_platform_admin()) with check(public.has_org_role(id,array['owner','admin']::public.org_role[]) or public.is_platform_admin());
create policy members_read on public.organization_members for select to authenticated using(public.is_org_member(organization_id) or public.is_platform_admin());
create table public.invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,email text not null check(email=lower(trim(email))),role public.org_role not null,status public.invitation_status not null default 'pending',requires_explicit_acceptance boolean not null default false, invited_by uuid not null,accepted_by uuid,accepted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
grant select,insert on public.invitations to authenticated; grant all on public.invitations to service_role; alter table public.invitations enable row level security;
create unique index invitations_pending_unique on public.invitations(organization_id,email) where status='pending';
create policy invitations_read on public.invitations for select to authenticated using(public.is_platform_admin() or lower(email)=lower(auth.jwt()->>'email'));
create policy invitations_create on public.invitations for insert to authenticated with check(public.is_platform_admin() and invited_by=auth.uid());
create table public.municipalities(ibge_code text primary key check(ibge_code ~ '^[0-9]{7}$'),name text not null,state text not null check(state ~ '^[A-Z]{2}$'),state_name text not null);
grant select on public.municipalities to authenticated; grant all on public.municipalities to service_role; alter table public.municipalities enable row level security; create policy municipalities_read on public.municipalities for select to authenticated using(true);
create index municipalities_name_idx on public.municipalities(lower(name));
create table public.countries(iso2 text primary key check(iso2 ~ '^[A-Z]{2}$'),name text not null);
grant select on public.countries to authenticated; grant all on public.countries to service_role; alter table public.countries enable row level security; create policy countries_read on public.countries for select to authenticated using(true);
create function public.is_valid_cnpj(value text) returns boolean language plpgsql immutable set search_path=public as $$ declare i integer; total integer; digit integer; weights integer[]; begin if value !~ '^[0-9]{14}$' or value=repeat(substr(value,1,1),14) then return false; end if; weights:=array[5,4,3,2,9,8,7,6,5,4,3,2];total:=0; for i in 1..12 loop total:=total+substr(value,i,1)::integer*weights[i];end loop;digit:=11-(total%11);if digit>=10 then digit:=0;end if;if digit<>substr(value,13,1)::integer then return false;end if;weights:=array[6,5,4,3,2,9,8,7,6,5,4,3,2];total:=0;for i in 1..13 loop total:=total+substr(value,i,1)::integer*weights[i];end loop;digit:=11-(total%11);if digit>=10 then digit:=0;end if;return digit=substr(value,14,1)::integer;end $$;
create table public.companies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),cnpj text not null check(public.is_valid_cnpj(cnpj)),legal_name text not null check(length(trim(legal_name))>0),trade_name text not null default '',municipal_registration text not null default '',email text not null default '',phone text not null default '',postal_code text not null default '',street text not null default '',number text not null default '',complement text not null default '',district text not null default '',municipality_ibge_code text not null references public.municipalities(ibge_code),state text not null,status public.company_status not null default 'configuring',created_by uuid not null,updated_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),change_origin public.change_origin not null default 'panel',unique(organization_id,cnpj));
grant select,insert,update on public.companies to authenticated;grant all on public.companies to service_role;alter table public.companies enable row level security;
create policy companies_read on public.companies for select to authenticated using(public.is_org_member(organization_id) or public.is_platform_admin());
create policy companies_create on public.companies for insert to authenticated with check(public.has_org_role(organization_id,array['owner','admin','operator','developer']::public.org_role[]) or public.is_platform_admin());
create policy companies_update on public.companies for update to authenticated using(public.has_org_role(organization_id,array['owner','admin','operator','developer']::public.org_role[]) or public.is_platform_admin()) with check(public.has_org_role(organization_id,array['owner','admin','operator','developer']::public.org_role[]) or public.is_platform_admin());
create index companies_org_idx on public.companies(organization_id);
create function public.audit_company() returns trigger language plpgsql set search_path=public as $$ begin select state into new.state from public.municipalities where ibge_code=new.municipality_ibge_code;if new.state is null then raise exception 'Invalid municipality';end if;if TG_OP='INSERT' then new.created_by:=auth.uid();new.created_at:=now();else if new.organization_id<>old.organization_id then raise exception 'Organization is immutable';end if;new.created_by:=old.created_by;new.created_at:=old.created_at;end if;new.updated_by:=auth.uid();new.updated_at:=now();new.change_origin:='panel';return new;end $$;
create trigger companies_audit before insert or update on public.companies for each row execute function public.audit_company();
create function public.touch_record() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at:=now();if TG_TABLE_NAME='organizations' then if new.slug<>old.slug then raise exception 'Slug is immutable';end if;new.created_by:=old.created_by;new.created_at:=old.created_at;end if;return new;end $$;
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_record();create trigger organizations_touch before update on public.organizations for each row execute function public.touch_record();create trigger invitations_touch before update on public.invitations for each row execute function public.touch_record();
create function public.create_user_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict do nothing;return new;end $$;
create trigger notem_create_profile after insert on auth.users for each row execute function public.create_user_profile();
insert into public.profiles(id,display_name) select id,coalesce(raw_user_meta_data->>'full_name','') from auth.users on conflict do nothing;
create function public.accept_invitation(invitation_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare inv public.invitations;verified_email text;begin select lower(email) into verified_email from auth.users where id=auth.uid() and email_confirmed_at is not null;if verified_email is null then raise exception 'Verified sign-in required';end if;select * into inv from public.invitations where id=invitation_id and status='pending' and email=verified_email for update;if inv.id is null then raise exception 'Invitation unavailable';end if;insert into public.organization_members(organization_id,user_id,role) values(inv.organization_id,auth.uid(),inv.role) on conflict(organization_id,user_id) do nothing;update public.invitations set status='accepted',accepted_by=auth.uid(),accepted_at=now() where id=inv.id;return inv.organization_id;end $$;
revoke all on function public.accept_invitation(uuid) from public;grant execute on function public.accept_invitation(uuid) to authenticated;
create function public.pending_invitations() returns table(id uuid,organization_id uuid,organization_name text,role public.org_role,requires_explicit_acceptance boolean) language sql stable security definer set search_path=public as $$ select i.id,i.organization_id,o.name,i.role,i.requires_explicit_acceptance from public.invitations i join public.organizations o on o.id=i.organization_id where i.status='pending' and i.email=(select lower(email) from auth.users where id=auth.uid() and email_confirmed_at is not null) $$;
revoke all on function public.pending_invitations() from public;grant execute on function public.pending_invitations() to authenticated;
alter table public.profiles add constraint profiles_last_org_fk foreign key(last_organization_id) references public.organizations(id) on delete set null;